INSERT INTO meal_recipes (id, name, description, instructions, servings, calories_per_serving, protein_g, fat_g, carb_g, goal_tags, serving_notes, tips, expert_advice, suggested_combo, created_at, updated_at) VALUES ('recipe-pancake-vi-tra-sua', 'Pancake vị trà sữa', 'Cách làm món pancake vị trà sữa đơn giản lại có hương vị cực kỳ hấp dẫn. Chỉ cần bỏ chút thời gian thôi là có ngay món ngon tiếp đãi bạn bè rồi nè! Nào vào', 'Chưa có hướng dẫn chi tiết.', 1, 0, 0, 0, 0, NULL, 'Xếp bánh pancake lên dĩa, thêm topping xốt trà sữa hình trái tim lên trên, rắc kẹo đường để trang trí.', '🧑‍🍳 Pha Trà sữa Royal Blendy® với nước sôi để bột tan hoàn toàn và dễ hòa quyện hơn khi trộn.🧑‍🍳 Pha hơi đặc phần trà sữa trộn với whipping cream để không làm kem bị chảy mềm.🧑‍🍳 Dùng Bột bánh rán pha sẵn để thuận tiện hơn và chiếc bánh rán vẫn đảm bảo xốp mềm thơm ngon.', NULL, NULL, '2026-08-07T22:02:58.523Z', '2026-08-07T22:02:58.523Z');
INSERT INTO meal_recipe_ingredients (id, recipe_id, food_id, name, quantity, unit, note, raw_text, sort_order) VALUES ('4f311ea9-7126-4608-a1d6-1a0625d2456d', 'recipe-pancake-vi-tra-sua', NULL, 'Whipping cream', 100, 'g', NULL, 'Whipping cream 100g', 0);
